// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract AiverseCoinV1_0_3 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ERC20Upgradeable,
    ReentrancyGuardUpgradeable
{
    uint256 public constant HALVING_PERIOD_DAYS = 1460;
    uint256 public constant MAX_TOTAL_SUPPLY = 210_000_000_000 ether;

    uint256 public initialDailyReward;
    uint256 public startDay;
    address public stakeController;
    uint256 public lastMintedDay;

    function initialize(
        string memory name_,
        string memory symbol_
    ) public initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __ERC20_init(name_, symbol_);
        __ReentrancyGuard_init();
        startDay = block.timestamp / 1 days;
        initialDailyReward = (MAX_TOTAL_SUPPLY / 2) / HALVING_PERIOD_DAYS;
    }

    function version() public pure returns (string memory) {
        return "1.0.3";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function setStakeController(
        address _stakeController
    ) external onlyOwner whenNotPaused {
        require(
            _stakeController != address(0),
            "Invalid stake controller address"
        );
        stakeController = _stakeController;
    }

    function mintToken() external nonReentrant whenNotPaused {
        require(msg.sender == stakeController, "Only StakeController can mint");
        uint256 currentDay = block.timestamp / 1 days;
        require(currentDay > lastMintedDay, "Already minted for today");

        uint256 amount = getMintAmountByDay(currentDay);
        require(
            totalSupply() + amount <= MAX_TOTAL_SUPPLY,
            "Exceeds max supply"
        );

        lastMintedDay = currentDay;
        _mint(address(this), amount);
    }

    function userClaimToken(
        address userAddr,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        require(
            msg.sender == stakeController,
            "Only StakeController can transfer"
        );
        _transfer(address(this), userAddr, amount);
    }

    function getMintAmountByDay(uint256 day) public view returns (uint256) {
        require(day >= startDay, "Invalid day");

        uint256 daysSinceStart = day - startDay;
        uint256 halvingEra = daysSinceStart / HALVING_PERIOD_DAYS;

        uint256 reward = initialDailyReward >> halvingEra;
        return reward;
    }
}

contracts/V1.0.3/NodeManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract NodeManagerV1_0_3 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    address[] public nodeList;
    mapping(address => bool) public isNode;

    event NodeAdded(address node);
    event NodeRemoved(address node);

    modifier onlyNode() {
        require(isNode[msg.sender], "Caller is not a valid node");
        _;
    }

    function initialize() public virtual initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __ReentrancyGuard_init();
    }

    function version() public pure returns (string memory) {
        return "1.0.3";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function getNodeList() external view returns (address[] memory) {
        return nodeList;
    }

    function addNode(address node) external onlyOwner whenNotPaused {
        require(!isNode[node], "Node already exists");
        require(node != address(0), "Invalid node address");
        isNode[node] = true;
        nodeList.push(node);
        emit NodeAdded(node);
    }

    function removeNode(address node) external onlyOwner whenNotPaused {
        require(isNode[node], "Node not found");
        for (uint256 i = 0; i < nodeList.length; i++) {
            if (nodeList[i] == node) {
                nodeList[i] = nodeList[nodeList.length - 1];
                nodeList.pop();
                break;
            }
        }
        isNode[node] = false;
        emit NodeRemoved(node);
    }
}

contracts/V1.0.4/CheckInManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

interface IAccountRegistrar {
    function userEmailHash(address user) external view returns (bytes32);
}

interface IPowerAsset {
    function mintCheckInRewards(
        address user,
        address checkInNode,
        address verifierNode
    ) external;
}

interface INodeManager {
    function owner() external view returns (address);

    function isNode(address addr) external view returns (bool);

    function getNodeList() external view returns (address[] memory);
}

contract CheckInManagerV1_0_4 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable
{
    using ECDSA for bytes32;

    INodeManager public nodeManager;
    IAccountRegistrar public accountRegistrar;
    IPowerAsset public powerAsset;

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;
    bytes32 private constant _CHECKIN_TYPEHASH =
        keccak256(
            "CheckIn(address userAddr,address checkInNode,uint256 nonce,uint256 chainid,uint256 expireAt)"
        );

    mapping(address => uint256) public nonces;
    mapping(address => mapping(uint256 => bool)) public checkedIn;
    mapping(address => mapping(uint256 => address)) public verifierNodeForDay;

    event VerifierNodeSelected(
        address indexed userAddr,
        address indexed verifierNode,
        uint256 indexed day
    );
    event CheckedIn(
        address indexed userAddr,
        address indexed checkInNode,
        address indexed verifierNode,
        uint256 day
    );

    function initialize(
        address _nodeManagerAddr,
        address _registrarAddr,
        address _powerAssetAddr
    ) public virtual initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __EIP712_init("Aiverse-CheckIn-Manager", "1");
        __ReentrancyGuard_init();

        nodeManager = INodeManager(_nodeManagerAddr);
        accountRegistrar = IAccountRegistrar(_registrarAddr);
        powerAsset = IPowerAsset(_powerAssetAddr);
    }

    function version() public pure returns (string memory) {
        return "1.0.4";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function selectRandomVerifierNode(
        address userAddr
    ) external nonReentrant whenNotPaused returns (address) {
        require(userAddr != address(0), "Invalid user address");

        _checkIsNode(msg.sender);
        address[] memory nodeListArray = nodeManager.getNodeList();
        require(nodeListArray.length > 1, "Not enough nodes");

        uint256 today = _getToday();
        require(
            verifierNodeForDay[userAddr][today] == address(0),
            "Already selected today"
        );

        uint256 randomSeed = uint256(
            keccak256(
                abi.encodePacked(
                    blockhash(block.number - 1) != bytes32(0)
                        ? blockhash(block.number - 1)
                        : blockhash(block.number - 2),
                    block.prevrandao,
                    block.timestamp,
                    userAddr,
                    nonces[userAddr]
                )
            )
        );

        uint256 startIndex = randomSeed % nodeListArray.length;

        address verifierNode;
        for (uint256 i = 0; i < nodeListArray.length; i++) {
            uint256 idx = (startIndex + i) % nodeListArray.length;
            if (nodeListArray[idx] != msg.sender) {
                verifierNode = nodeListArray[idx];
                break;
            }
        }

        verifierNodeForDay[userAddr][today] = verifierNode;
        emit VerifierNodeSelected(userAddr, verifierNode, today);
        return verifierNode;
    }

    function checkIn(
        address userAddr,
        address checkInNode,
        uint256 expireAt,
        bytes memory userSig,
        bytes memory checkInNodeSig
    ) external nonReentrant whenNotPaused {
        require(userAddr != address(0), "Invalid user address");

        _checkIsNode(msg.sender);
        _checkIsNode(checkInNode);
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );

        uint256 today = _getToday();
        require(
            accountRegistrar.userEmailHash(userAddr) != bytes32(0),
            "User not registered"
        );
        require(!checkedIn[userAddr][today], "Already checked today");

        address verifierNode = verifierNodeForDay[userAddr][today];
        require(verifierNode == msg.sender, "Non-designated verifier node");

        bytes32 structHash = keccak256(
            abi.encode(
                _CHECKIN_TYPEHASH,
                userAddr,
                checkInNode,
                nonces[userAddr],
                block.chainid,
                expireAt
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);

        address recoveredUser = digest.recover(userSig);
        require(recoveredUser == userAddr, "Invalid user signature");

        address recoveredCheckInNode = digest.recover(checkInNodeSig);
        require(
            recoveredCheckInNode == checkInNode,
            "Invalid checkIn node signature"
        );

        checkedIn[userAddr][today] = true;
        nonces[userAddr]++;
        powerAsset.mintCheckInRewards(userAddr, checkInNode, msg.sender);

        emit CheckedIn(userAddr, checkInNode, msg.sender, today);
    }

    function hasCheckedInToday(address userAddr) external view returns (bool) {
        return checkedIn[userAddr][_getToday()];
    }

    function getNonce(address userAddr) external view returns (uint256) {
        return nonces[userAddr];
    }

    function getVerifierNodeForToday(
        address userAddr
    ) external view returns (address) {
        return verifierNodeForDay[userAddr][_getToday()];
    }

    function _checkIsNode(address addr) internal view {
        require(nodeManager.isNode(addr), "Invalid Node");
    }

    function _getToday() internal view returns (uint256) {
        return block.timestamp / 1 days;
    }
}

contracts/V1.0.4/PowerAsset.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";

interface IAccountRegistrar {
    function referral(address userAddr) external view returns (address);
}

contract PowerAssetV1_0_4 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable,
    ERC20Upgradeable
{
    using ECDSA for bytes32;

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;
    bytes32 private constant _TRANSFER_TYPEHASH =
        keccak256(
            "Transfer(address from,address to,uint256 amount,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );

    uint256 public startTime;
    address public accountRegistrar;
    address public checkInManager;
    address public stakeController;

    mapping(address => uint256) public nonces;
    mapping(address => bool) public authorizedContracts;

    event Mint(address indexed to, uint256 amount);

    function initialize(
        string memory name_,
        string memory symbol_
    ) public virtual initializer {
        __Ownable_init(msg.sender);
        __EIP712_init("Aiverse-Power-Asset", "1");
        __Pausable_init();
        __ReentrancyGuard_init();
        __ERC20_init(name_, symbol_);
        startTime = block.timestamp;
    }

    function version() public pure returns (string memory) {
        return "1.0.4";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function setAccountRegistrar(
        address _accountRegistrar
    ) external onlyOwner whenNotPaused {
        require(_accountRegistrar != address(0), "Invalid address");
        accountRegistrar = _accountRegistrar;
    }

    function setCheckInManager(
        address _checkInManager
    ) external onlyOwner whenNotPaused {
        require(_checkInManager != address(0), "Invalid address");
        checkInManager = _checkInManager;
    }

    function setStakeController(
        address _stakeController
    ) external onlyOwner whenNotPaused {
        require(_stakeController != address(0), "Invalid address");
        stakeController = _stakeController;
    }

    function setAuthorizedContract(
        address contractAddr,
        bool authorized
    ) external onlyOwner whenNotPaused {
        require(contractAddr != address(0), "Invalid contract address");
        authorizedContracts[contractAddr] = authorized;
    }

    function transfer(
        address to,
        uint256 amount
    ) public override nonReentrant whenNotPaused returns (bool) {
        return super.transfer(to, amount);
    }

    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) public override nonReentrant whenNotPaused returns (bool) {
        require(
            msg.sender == stakeController || authorizedContracts[msg.sender],
            "Only StakeController or authorized contracts can transfer"
        );
        _transfer(from, to, amount);
        return true;
    }

    function transferWithSig(
        address from,
        address to,
        uint256 amount,
        uint256 expireAt,
        bytes memory fromSignature
    ) external nonReentrant whenNotPaused {
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );

        bytes32 structHash = keccak256(
            abi.encode(
                _TRANSFER_TYPEHASH,
                from,
                to,
                amount,
                nonces[from],
                block.chainid,
                expireAt,
                msg.sender
            )
        );

        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(fromSignature);
        require(recovered == from, "Invalid signature");
        nonces[from]++;

        _transfer(from, to, amount);
    }

    function mintRegistrationRewards(
        address userAddr,
        address foundationNode
    ) external nonReentrant whenNotPaused {
        require(
            msg.sender == accountRegistrar,
            "Only AccountRegistrar can mint"
        );
        require(
            userAddr != address(0) && foundationNode != address(0),
            "Invalid address"
        );

        uint256 divisor = _getCurrentDivisor();

        uint256 userReward = (100 * 10 ** decimals()) / divisor;
        uint256 foundationNodeReward = (25 * 10 ** decimals()) / divisor;

        _mint(userAddr, userReward);
        _mint(foundationNode, foundationNodeReward);

        emit Mint(userAddr, userReward);
        emit Mint(foundationNode, foundationNodeReward);
    }

    function mintCheckInRewards(
        address userAddr,
        address checkInNode,
        address verifierNode
    ) external nonReentrant whenNotPaused {
        require(msg.sender == checkInManager, "Only CheckInManager can mint");
        require(
            userAddr != address(0) &&
                checkInNode != address(0) &&
                verifierNode != address(0),
            "Invalid address"
        );
        address referer = IAccountRegistrar(accountRegistrar).referral(
            userAddr
        );

        uint256 divisor = _getCurrentDivisor();

        uint256 userReward = (20 * 10 ** decimals()) / divisor;
        uint256 checkInNodeReward = (3 * 10 ** decimals()) / divisor;
        uint256 verifierReward = (2 * 10 ** decimals()) / divisor;
        uint256 refererReward = (5 * 10 ** decimals()) / divisor;

        _mint(userAddr, userReward);
        _mint(checkInNode, checkInNodeReward);
        _mint(verifierNode, verifierReward);
        _mint(referer, refererReward);

        emit Mint(userAddr, userReward);
        emit Mint(checkInNode, checkInNodeReward);
        emit Mint(verifierNode, verifierReward);
        emit Mint(referer, refererReward);
    }

    function _getCurrentDivisor() internal view returns (uint256) {
        uint256 yearsSinceStart = (block.timestamp - startTime) / (365 days);
        uint256 divisor = 2 ** Math.min(yearsSinceStart / 4, 255);
        require(divisor > 0, "Divisor cannot be zero");
        return divisor;
    }
}

contracts/V1.0.7/StakeController.sol.content:
// // SPDX-License-Identifier: MIT

pragma solidity ^0.8.28;
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";

interface IPowerAsset {
    function transfer(address to, uint256 amount) external;

    function transferFrom(address from, address to, uint256 amount) external;
}

interface INodeManager {
    function owner() external view returns (address);

    function isNode(address addr) external view returns (bool);

    function getNodeList() external view returns (address[] memory);
}

interface IAiverseCoin {
    function getMintAmountByDay(uint256 day) external view returns (uint256);

    function mintToken() external;

    function userClaimToken(address userAddr, uint256 amount) external;
}

contract StakeControllerV1_0_7 is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    ReentrancyGuardUpgradeable
{
    using ECDSA for bytes32;

    struct StakeInfo {
        uint256 power;
        uint256 lastSettledDay;
        uint256 unclaimedReward;
    }

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;
    bytes32 private constant _STAKE_TYPEHASH =
        keccak256(
            "Stake(address userAddr,address node,uint256 amount,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );
    bytes32 private constant _UNSTAKE_TYPEHASH =
        keccak256(
            "Unstake(address userAddr,address node,uint256 amount,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );
    bytes32 private constant _CLAIM_TYPEHASH =
        keccak256(
            "Claim(address userAddr,address node,uint256 nonce,uint256 chainid,uint256 expireAt,address executor)"
        );

    uint256 public constant MINE_REWARD_PERCENTAGE = 80;
    uint256 constant NODE_REWARD_COEF = 20;
    uint256 constant USER_REWARD_COEF = 80;
    uint256 public constant MAX_DAYS_FOR_REWARD = 7;

    mapping(address => uint256) public nonces;
    mapping(uint256 => uint256) public rewardPerPower;
    mapping(address => uint256) public nodeTotalPower;
    mapping(address => uint256) public nodeLastSettledDay;
    mapping(uint256 => uint256) public totalPowerSnapshot;
    mapping(uint256 => mapping(address => uint256))
        public nodeTotalPowerSnapshot;
    mapping(address => mapping(address => bool)) public isUserStakedOnNode;
    mapping(address => mapping(address => StakeInfo)) public userStakeInfo;
    mapping(address => address[]) public userStakedNodes;

    uint256 public currentSnapshotDay;
    uint256 public totalPower;
    address public aicoinAddr;
    address public powerAssetAddr;
    address public nodeManagerAddr;

    event Staked(
        address indexed userAddr,
        address indexed node,
        uint256 amount
    );
    event Unstaked(
        address indexed userAddr,
        address indexed node,
        uint256 amount
    );
    event UserClaimReward(
        address indexed userAddr,
        address indexed node,
        uint256 reward
    );
    event NodeClaimReward(address indexed node, uint256 reward);

    function initialize(
        address _aicoinAddr,
        address _powerAssetAddr,
        address _nodeManagerAddr
    ) public initializer {
        __Ownable_init(msg.sender);
        __Pausable_init();
        __EIP712_init("Aiverse-Stake-Controller", "1");
        __ReentrancyGuard_init();

        aicoinAddr = _aicoinAddr;
        powerAssetAddr = _powerAssetAddr;
        nodeManagerAddr = _nodeManagerAddr;
    }

    function version() public pure returns (string memory) {
        return "1.0.7";
    }

    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    function getUserUnclaimReward(
        address userAddr,
        address node
    ) external view returns (uint256) {
        StakeInfo memory stakeInfo = userStakeInfo[userAddr][node];
        uint256 _unsettleReward = _calculateUserReward(
            stakeInfo.power,
            stakeInfo.lastSettledDay,
            currentSnapshotDay
        );
        return _unsettleReward + stakeInfo.unclaimedReward;
    }

    function getNodeUnclaimReward(
        address node
    ) external view returns (uint256) {
        uint256 lastSettledDay = nodeLastSettledDay[node];
        return _calculateNodeReward(node, lastSettledDay, currentSnapshotDay);
    }

    function stake(
        address node,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        IPowerAsset(powerAssetAddr).transfer(address(this), amount);
        _stake(msg.sender, node, amount);
    }

    function stakeWithSig(
        address userAddr,
        address node,
        uint256 amount,
        uint256 expireAt,
        bytes memory userSig
    ) external nonReentrant whenNotPaused {
        require(amount > 0, "Invalid amount");
        _checkSigExpire(expireAt);

        bytes32 structHash = keccak256(
            abi.encode(
                _STAKE_TYPEHASH,
                userAddr,
                node,
                amount,
                nonces[userAddr],
                block.chainid,
                expireAt,
                msg.sender
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(userSig);
        require(recovered == userAddr, "Invalid signature");

        nonces[userAddr]++;

        IPowerAsset(powerAssetAddr).transferFrom(
            userAddr,
            address(this),
            amount
        );

        _stake(userAddr, node, amount);
    }

    function unstake(
        address node,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        _unstake(msg.sender, node, amount);
        IPowerAsset(powerAssetAddr).transfer(msg.sender, amount);
    }

    function unstakeWithSig(
        address userAddr,
        address node,
        uint256 amount,
        uint256 expireAt,
        bytes memory userSig
    ) external nonReentrant whenNotPaused {
        require(amount > 0, "Invalid amount");
        _checkSigExpire(expireAt);

        bytes32 structHash = keccak256(
            abi.encode(
                _UNSTAKE_TYPEHASH,
                userAddr,
                node,
                amount,
                nonces[userAddr],
                block.chainid,
                expireAt,
                msg.sender
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(userSig);
        require(recovered == userAddr, "Invalid signature");

        nonces[userAddr]++;

        _unstake(userAddr, node, amount);

        IPowerAsset(powerAssetAddr).transferFrom(
            address(this),
            userAddr,
            amount
        );
    }

    function nodeClaimReward() external nonReentrant whenNotPaused {
        _checkIsNode(msg.sender);
        _nodeClaimReward(msg.sender);
    }

    function userClaimReward(address node) external nonReentrant whenNotPaused {
        _userClaimReward(msg.sender, node);
    }

    function userClaimRewardWithSig(
        address userAddr,
        address node,
        uint256 expireAt,
        bytes memory userSig
    ) external nonReentrant whenNotPaused {
        _checkSigExpire(expireAt);

        bytes32 structHash = keccak256(
            abi.encode(
                _CLAIM_TYPEHASH,
                userAddr,
                node,
                nonces[userAddr],
                block.chainid,
                expireAt,
                msg.sender
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(userSig);
        require(recovered == userAddr, "Invalid signature");

        nonces[userAddr]++;

        _userClaimReward(userAddr, node);
    }

    function dailySettle() external onlyOwner nonReentrant whenNotPaused {
        uint256 currentDay = _getCurrentDay();
        require(currentDay > currentSnapshotDay, "Already Snapshot today");
        IAiverseCoin(aicoinAddr).mintToken();
        totalPowerSnapshot[currentDay] = totalPower;
        uint256 totalReward = IAiverseCoin(aicoinAddr).getMintAmountByDay(
            currentDay
        );
        uint256 mineReward = (totalReward * MINE_REWARD_PERCENTAGE) / 100;
        uint256 foundationReward = totalReward - mineReward;
        _transferToken(INodeManager(nodeManagerAddr).owner(), foundationReward);

        address[] memory allNodes = INodeManager(nodeManagerAddr).getNodeList();
        for (uint i = 0; i < allNodes.length; i++) {
            address node = allNodes[i];
            nodeTotalPowerSnapshot[currentDay][node] = nodeTotalPower[node];
        }

        if (totalPower > 0) {
            uint256 unitReward = (mineReward * 1e18) / totalPower;
            rewardPerPower[currentDay] = unitReward;
        } else {
            rewardPerPower[currentDay] = 0;
        }

        currentSnapshotDay = currentDay;
    }

    function _stake(address userAddr, address node, uint256 amount) internal {
        _checkIsNode(node);
        require(amount > 0, "Amount must be greater than 0");

        if (!isUserStakedOnNode[userAddr][node]) {
            isUserStakedOnNode[userAddr][node] = true;
            userStakedNodes[userAddr].push(node);
        }

        uint256 currentDay = currentSnapshotDay;
        _settleUserPendingRewards(userAddr, node, currentDay);

        userStakeInfo[userAddr][node].power += amount;
        nodeTotalPower[node] += amount;
        totalPower += amount;

        emit Staked(userAddr, node, amount);
    }

    function _unstake(address userAddr, address node, uint256 amount) internal {
        _checkIsNode(node);
        require(amount > 0, "Amount must be greater than 0");
        require(
            userStakeInfo[userAddr][node].power >= amount,
            "Insufficient staked amount"
        );

        uint256 currentDay = currentSnapshotDay;
        _settleUserPendingRewards(userAddr, node, currentDay);

        userStakeInfo[userAddr][node].power -= amount;
        nodeTotalPower[node] -= amount;
        totalPower -= amount;

        emit Unstaked(userAddr, node, amount);
    }

    function _nodeClaimReward(address node) internal {
        uint256 currentDay = currentSnapshotDay;
        uint256 lastSettledDay = nodeLastSettledDay[node];

        uint256 reward = _calculateNodeReward(node, lastSettledDay, currentDay);
        require(reward > 0, "No rewards available");

        nodeLastSettledDay[node] = currentDay;

        _transferToken(node, reward);
        emit NodeClaimReward(node, reward);
    }

    function _userClaimReward(address userAddr, address node) internal {
        StakeInfo storage info = userStakeInfo[userAddr][node];

        if (info.power > 0) {
            uint256 currentDay = currentSnapshotDay;
            _settleUserPendingRewards(userAddr, node, currentDay);
        }

        uint256 reward = info.unclaimedReward;
        require(reward > 0, "No rewards available");

        info.unclaimedReward = 0;

        _transferToken(userAddr, reward);
        emit UserClaimReward(userAddr, node, reward);
    }

    function _transferToken(address to, uint256 amount) internal {
        IAiverseCoin(aicoinAddr).userClaimToken(to, amount);
    }

    function _settleUserPendingRewards(
        address userAddr,
        address node,
        uint256 currentDay
    ) internal {
        StakeInfo storage stakeInfo = userStakeInfo[userAddr][node];
        uint256 lastSettledDay = stakeInfo.lastSettledDay;
        uint256 reward = _calculateUserReward(
            stakeInfo.power,
            lastSettledDay,
            currentDay
        );
        if (reward > 0) {
            stakeInfo.unclaimedReward += reward;
            stakeInfo.lastSettledDay = currentDay;
        }
    }

    function _calculateNodeReward(
        address node,
        uint256 lastSettledDay,
        uint256 currentDay
    ) internal view returns (uint256) {
        uint256 nodeRewardScaled = 0;
        if (currentDay > lastSettledDay) {
            uint256 correctLastSettledDay = Math.max(
                currentDay - MAX_DAYS_FOR_REWARD,
                lastSettledDay
            );
            for (
                uint256 day = correctLastSettledDay + 1;
                day <= currentDay;
                day++
            ) {
                uint256 rewardPerUnit = rewardPerPower[day];
                uint256 powerSnapShot = nodeTotalPowerSnapshot[day][node];
                nodeRewardScaled +=
                    (rewardPerUnit * powerSnapShot * NODE_REWARD_COEF) /
                    100;
            }
        }

        return nodeRewardScaled / 1e18;
    }

    function _calculateUserReward(
        uint256 power,
        uint256 lastSettledDay,
        uint256 currentDay
    ) internal view returns (uint256) {
        uint256 userRewardScaled = 0;

        if (currentDay > lastSettledDay) {
            uint256 correctLastSettledDay = Math.max(
                currentDay - MAX_DAYS_FOR_REWARD,
                lastSettledDay
            );
            for (
                uint256 day = correctLastSettledDay + 1;
                day <= currentDay;
                day++
            ) {
                uint256 rewardPerUnit = rewardPerPower[day];
                userRewardScaled +=
                    (rewardPerUnit * power * USER_REWARD_COEF) /
                    100;
            }
        }

        return userRewardScaled / 1e18;
    }

    function _getCurrentDay() internal view returns (uint256) {
        return block.timestamp / 1 days;
    }

    function _checkIsNode(address addr) internal view {
        require(INodeManager(nodeManagerAddr).isNode(addr), "Invalid Caller");
    }

    function _checkSigExpire(uint256 expireAt) internal view {
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );
    }
}

